!> Constructs a Givens plane rotation.
!
! ## Notes
!
! * Modified version of reference BLAS level1 routine (version 3.7.0). Updated to "free form" Fortran 95.
!
! ## Authors
!
! * Univ. of Tennessee
! * Univ. of California Berkeley
! * Univ. of Colorado Denver
! * NAG Ltd.
!
! ## References
!
! * Anderson E. (2017) Algorithm 978: Safe Scaling in the Level 1 BLAS. ACM Trans Math Softw 44:1--28. doi:[10.1145/3061665](https://doi.org/10.1145/3061665)
!
! ## License
!
! From <http://netlib.org/blas/faq.html>:
!
! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
! >
! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
! >
! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
! >
! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {real} a - rotational elimination parameter
! @param {real} b - rotational elimination parameter
! @param {real} c - cosine of the angle of rotation
! @param {real} s - sine of the angle of rotation
!<
subroutine srotg( a, b, c, s )
  implicit none
  ! ..
  ! Internal parameters:
  integer, parameter :: wp = kind(1.e0)
  ! ..
  ! Constants:
  real(wp), parameter :: zero = 0.0_wp
  real(wp), parameter :: one  = 1.0_wp
  ! ..
  ! Scalar Arguments:
  real(wp) :: a, b, c, s
  ! ..
  ! Local Scalars:
  real(wp) :: anorm, bnorm, scl, sigma, r, z, safmin, safmax
  ! ..
  ! Compute safe scaling constants using F95-compatible intrinsics:
  safmin = tiny( 1.0_wp ) * ( 1.0_wp / epsilon( 1.0_wp ) )
  safmax = huge( 1.0_wp ) * epsilon( 1.0_wp )
  ! ..
  anorm = abs(a)
  bnorm = abs(b)
  if( bnorm == zero ) then
    c = one
    s = zero
    b = zero
  else if( anorm == zero ) then
    c = zero
    s = one
    a = b
    b = one
  else
    scl = min( safmax, max( safmin, anorm, bnorm ) )
    if( anorm > bnorm ) then
      sigma = sign(one,a)
    else
      sigma = sign(one,b)
    end if
    r = sigma*( scl*sqrt((a/scl)**2 + (b/scl)**2) )
    c = a/r
    s = b/r
    if( anorm > bnorm ) then
      z = s
    else if( c /= zero ) then
      z = one/c
    else
      z = one
    end if
    a = r
    b = z
  end if
  return
end subroutine srotg
